package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type TransferRequest struct {
	FromAccount string `json:"from_account"`
	ToAccount   string `json:"to_account"`
	Amount      float64 `json:"amount"`
	Memo        string `json:"memo"`
}

func initDB() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func getBalance(w http.ResponseWriter, r *http.Request) {
	acctID := r.URL.Query().Get("id")
	if acctID == "" {
		http.Error(w, "missing id", 400)
		return
	}
	// Parameterized query - safe
	row := db.QueryRow("SELECT balance FROM accounts WHERE account_id = $1", acctID)
	var balance float64
	if err := row.Scan(&balance); err != nil {
		http.Error(w, "not found", 404)
		return
	}
	json.NewEncoder(w).Encode(map[string]float64{"balance": balance})
}

func transfer(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req TransferRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", 400)
		return
	}

	if req.Amount <= 0 {
		http.Error(w, "invalid amount", 400)
		return
	}

	// Check balance first
	var currentBalance float64
	err := db.QueryRow("SELECT balance FROM accounts WHERE account_id = $1", req.FromAccount).Scan(&currentBalance)
	if err != nil {
		http.Error(w, "source account not found", 404)
		return
	}

	if currentBalance < req.Amount {
		http.Error(w, "insufficient funds", 400)
		return
	}

	// Execute transfer - VULNERABLE: memo field is concatenated into SQL
	// The memo is inserted into an audit log entry using string formatting
	auditQuery := fmt.Sprintf(
		"INSERT INTO transfer_log (from_acct, to_acct, amount, memo, ts) VALUES ('%s', '%s', %f, '%s', NOW())",
		req.FromAccount, req.ToAccount, req.Amount, req.Memo,
	)

	tx, err := db.Begin()
	if err != nil {
		http.Error(w, "internal error", 500)
		return
	}

	_, err = tx.Exec("UPDATE accounts SET balance = balance - $1 WHERE account_id = $2", req.Amount, req.FromAccount)
	if err != nil {
		tx.Rollback()
		http.Error(w, "debit failed", 500)
		return
	}

	_, err = tx.Exec("UPDATE accounts SET balance = balance + $1 WHERE account_id = $2", req.Amount, req.ToAccount)
	if err != nil {
		tx.Rollback()
		http.Error(w, "credit failed", 500)
		return
	}

	// Audit log with vulnerable query
	_, err = tx.Exec(auditQuery)
	if err != nil {
		// Log error but don't fail the transfer
		log.Printf("audit log failed: %v (query: %s)", err, auditQuery)
	}

	if err := tx.Commit(); err != nil {
		http.Error(w, "commit failed", 500)
		return
	}

	w.WriteHeader(200)
	json.NewEncoder(w).Encode(map[string]string{"status": "completed"})
}

func searchTransfers(w http.ResponseWriter, r *http.Request) {
	acctID := r.URL.Query().Get("account")
	keyword := r.URL.Query().Get("keyword")

	// VULNERABLE: keyword is concatenated
	query := "SELECT from_acct, to_acct, amount, memo, ts FROM transfer_log WHERE (from_acct = '" + acctID + "' OR to_acct = '" + acctID + "')"
	if keyword != "" {
		query += " AND memo LIKE '%" + keyword + "%'"
	}
	query += " ORDER BY ts DESC LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, fmt.Sprintf("query error: %v", err), 500)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	for rows.Next() {
		var from, to, memo string
		var amount float64
		var ts string
		rows.Scan(&from, &to, &amount, &memo, &ts)
		results = append(results, map[string]interface{}{"from": from, "to": to, "amount": amount, "memo": memo, "ts": ts})
	}
	json.NewEncoder(w).Encode(results)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	fmt.Fprintf(w, "ok")
}

func main() {
	initDB()
	http.HandleFunc("/api/balance", getBalance)
	http.HandleFunc("/api/transfer", transfer)
	http.HandleFunc("/api/transfers/search", searchTransfers)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
